<template>
  <svg
    class="fd-bg-map"
    :class="activeLayer ? `is-layer-${activeLayer}` : ''"
    viewBox="0 0 420 420"
    aria-hidden="true"
    role="img"
  >
    <defs>
      <!-- Máscara radial de viñeta para fundir los bordes de la retícula -->
      <radialGradient
        id="bol-grad-vignette"
        cx="50%"
        cy="52%"
        r="54%"
      >
        <stop
          offset="0%"
          stop-color="#fff"
          stop-opacity="1"
        />
        <stop
          offset="70%"
          stop-color="#fff"
          stop-opacity="0.72"
        />
        <stop
          offset="100%"
          stop-color="#fff"
          stop-opacity="0"
        />
      </radialGradient>

      <mask id="bol-mask-vignette">
        <rect
          width="420"
          height="420"
          fill="url(#bol-grad-vignette)"
        />
      </mask>

      <!-- Relleno adaptativo al tema Verona activo -->
      <linearGradient
        id="bol-grad-territory"
        x1="15%"
        y1="10%"
        x2="85%"
        y2="90%"
      >
        <stop
          offset="0%"
          stop-color="var(--copper)"
          stop-opacity="0.24"
        />
        <stop
          offset="55%"
          stop-color="var(--sapphire)"
          stop-opacity="0.11"
        />
        <stop
          offset="100%"
          stop-color="var(--copper)"
          stop-opacity="0.04"
        />
      </linearGradient>

      <radialGradient
        id="bol-grad-halo-primary"
        cx="50%"
        cy="50%"
        r="50%"
      >
        <stop
          offset="0%"
          stop-color="var(--copper)"
          stop-opacity="0.65"
        />
        <stop
          offset="48%"
          stop-color="var(--copper)"
          stop-opacity="0.20"
        />
        <stop
          offset="100%"
          stop-color="var(--copper)"
          stop-opacity="0"
        />
      </radialGradient>

      <!-- Patrón de grilla catastral/predial dentro del territorio -->
      <pattern
        id="bol-pattern-catastro"
        width="16"
        height="16"
        patternUnits="userSpaceOnUse"
      >
        <path
          d="M 16 0 L 0 0 0 16"
          fill="none"
          stroke="var(--copper)"
          stroke-width="0.55"
        />
      </pattern>

      <!-- Patrón de tramado geomático diagonal -->
      <pattern
        id="bol-pattern-geomatica"
        width="10"
        height="10"
        patternTransform="rotate(35)"
        patternUnits="userSpaceOnUse"
      >
        <line
          x1="0"
          y1="0"
          x2="0"
          y2="10"
          stroke="var(--sapphire)"
          stroke-width="0.7"
        />
      </pattern>

      <!-- Recorte exacto al territorio de Bolivia en el viewBox 420x420 -->
      <clipPath id="bol-clip-territory">
        <path
          :d="BOLIVIA_PATH"
          transform="translate(-35,-10) scale(0.34) translate(200,200)"
        />
      </clipPath>
    </defs>

    <!-- 1. Retícula geodésica con viñeta suave -->
    <g
      class="bol-graticule"
      mask="url(#bol-mask-vignette)"
    >
      <line
        v-for="pos in [60, 120, 180, 240, 300, 360]"
        :key="`lat-${pos}`"
        x1="0"
        :y1="pos"
        x2="420"
        :y2="pos"
        class="bol-grid-line"
      />
      <line
        v-for="pos in [60, 120, 180, 240, 300, 360]"
        :key="`lon-${pos}`"
        :x1="pos"
        y1="0"
        :x2="pos"
        y2="420"
        class="bol-grid-line"
      />
    </g>

    <!-- 2. Etiquetas de coordenadas reales sobre extensión territorial de Bolivia -->
    <g
      class="bol-coords"
      font-size="9"
    >
      <text
        x="8"
        y="117"
      >12°S</text>
      <text
        x="8"
        y="177"
      >14°S</text>
      <text
        x="8"
        y="237"
      >17°S</text>
      <text
        x="8"
        y="297"
      >19°S</text>
      <text
        x="8"
        y="357"
      >22°S</text>

      <text
        x="63"
        y="14"
      >70°W</text>
      <text
        x="123"
        y="14"
      >67°W</text>
      <text
        x="183"
        y="14"
      >65°W</text>
      <text
        x="243"
        y="14"
      >62°W</text>
      <text
        x="303"
        y="14"
      >59°W</text>
    </g>

    <!-- 3. Cuerpo territorial y capas temáticas interactivas -->
    <g class="bol-territory">
      <g transform="translate(-35,-10) scale(0.34)">
        <g transform="translate(200,200)">
          <path
            class="bol-territory-fill"
            fill="url(#bol-grad-territory)"
            :d="BOLIVIA_PATH"
          />
        </g>
      </g>

      <!-- Capas internas recortadas al polígono nacional -->
      <g clip-path="url(#bol-clip-territory)">
        <!-- Malla catastral / predial -->
        <rect
          width="420"
          height="420"
          fill="url(#bol-pattern-catastro)"
          class="bol-thematic-layer bol-layer-catastro"
        />

        <!-- Tramado teledetección / geomática -->
        <rect
          width="420"
          height="420"
          fill="url(#bol-pattern-geomatica)"
          class="bol-thematic-layer bol-layer-geomatica"
        />

        <!-- Barrido HUD telemétrico -->
        <rect
          x="0"
          y="40"
          width="420"
          height="28"
          class="bol-scanline"
        />
      </g>
    </g>

    <!-- 4. Red de triangulación geodésica SIRGAS-BOL / enlaces Web-GIS -->
    <g class="bol-network">
      <!-- Red base (La Paz - CBB - SCZ - SRE - TJA - TDD - CIJ) -->
      <path
        d="M86 105 L100 233 L144 254 L211 263 L165 292 L176 350 M86 105 L173 194 L211 263 M173 194 L144 254 L165 292 L100 233"
        class="bol-triangulation"
      />
      <!-- Rutas animadas desde nodo maestro La Paz -->
      <path
        d="M100 233 Q122 232 144 254 T211 263"
        class="bol-arc bol-arc-main"
      />
      <path
        d="M100 233 Q125 268 165 292 L176 350"
        class="bol-arc bol-arc-sec"
      />
      <path
        d="M100 233 Q138 205 173 194 L86 105"
        class="bol-arc bol-arc-sec"
      />
    </g>

    <!-- 5. Nodos geodésicos departamentales -->
    <g class="bol-nodes">
      <g
        v-for="node in NODES"
        :key="node.id"
        :transform="`translate(${node.x}, ${node.y})`"
        :class="['bol-node', node.primary ? 'is-primary' : 'is-secondary']"
      >
        <template v-if="node.primary">
          <circle
            r="26"
            fill="url(#bol-grad-halo-primary)"
          />
          <circle
            class="bol-pulse bol-pulse-1"
            r="17"
          />
          <circle
            class="bol-pulse bol-pulse-2"
            r="11"
          />
          <circle
            r="5.5"
            class="bol-node-ring"
          />
          <circle
            r="2.2"
            class="bol-node-core"
          />
          <text
            x="0"
            y="-12"
            text-anchor="middle"
            class="bol-node-label is-main"
          >
            {{ node.name.toUpperCase() }}
          </text>
        </template>

        <template v-else>
          <circle
            r="8"
            class="bol-node-halo-sec"
          />
          <circle
            r="3"
            class="bol-node-dot-sec"
          />
          <text
            v-if="['SCZ', 'CBB', 'SRE', 'TDD'].includes(node.code)"
            :x="node.code === 'CBB' ? -8 : 8"
            :y="node.code === 'CBB' ? 11 : 3"
            :text-anchor="node.code === 'CBB' ? 'end' : 'start'"
            class="bol-node-label"
          >
            {{ node.code }}
          </text>
        </template>
      </g>
    </g>

    <!-- 6. Brújula geodésica minimalista en cuadrante NE despejado -->
    <g
      class="bol-compass"
      transform="translate(318, 128)"
    >
      <circle
        r="24"
        class="bol-compass-bg"
      />
      <circle
        r="19"
        class="bol-compass-ring"
      />
      <polygon
        points="0,-16 3.5,2 0,0"
        class="bol-compass-north"
      />
      <polygon
        points="0,-16 -3.5,2 0,0"
        class="bol-compass-north-shade"
      />
      <polygon
        points="0,16 3,2 0,0 -3,2"
