    </g>

    <!-- 7. Panel de escala / sistema de referencia geodésico -->
    <g
      class="bol-scale-panel"
      transform="translate(56, 372)"
    >
      <rect
        x="0"
        y="0"
        width="112"
        height="28"
        rx="5"
        class="bol-hud-card"
      />
      <text
        x="8"
        y="10"
        class="bol-hud-title"
      >SIRGAS-BOL · WGS84</text>
      <g transform="translate(8, 15)">
        <rect
          x="0"
          y="0"
          width="16"
          height="3.5"
          class="bol-scale-fill"
        />
        <rect
          x="16"
          y="0"
          width="16"
          height="3.5"
          class="bol-scale-empty"
        />
        <rect
          x="32"
